// gobal variables
let frogs = [];
let bColour;
let amountOfFrogs = 100;

function setup() {
	createCanvas(windowWidth, windowHeight);

	for(i = 0; i < amountOfFrogs; i++){
	frogs[i] = new Frog();
	}
	 bColour = color(random(255), random(255), random(255));
	background(bColour);
}

////////////////////////////////

function draw() {
	background(0);

	for(let frog of frogs){
		frog.draw();
	}
	fill(frogs[0].hue,255,255);
	strokeWeight(2);
	ellipse(width * 0.5, height * 0.125, 30);
}



// === Tab: frog ===
class Frog {
	constructor() {
		this.floor = this.y = height*0.9;		
		this.x = width * 0.5;
		this.counter = this.whichWay = 0;
		this.jumpHeight = 30;
		this.increment = 0.03
		this.hue = random(255);
		this.speed = random(5,10);
	}

	draw(){
		colorMode(HSB, 255);	
	 	stroke(this.hue+=0.004, 255, 150);
		strokeWeight(4);

		for (let i = 0; i < this.speed; i++) { // Changes how quick and long the frog is
			this.step();
			point(this.x, this.y);
		}

		if(this.hue>=255){
			this.hue = 0;
			 }
	}

	step() {	
			this.y = this.floor - (sin(this.counter += this.increment) * this.jumpHeight);
			this.x += this.whichWay;
			if (this.y > this.floor)this.newDirection()
	}

	newDirection(){		
			this.y = this.floor;

			let maxMove = 1;
			let minMove = 0.4;
			let randomValue = int(random(2));
			// Maps the amount of friction based on new direction and position. 
			let edgeFriction = map(this.x, 0, width, (randomValue?0:1), (randomValue?-1:0)); 
			this.whichWay = random(minMove*edgeFriction, maxMove*edgeFriction);

			this.jumpHeight = random(20, 500);
			this.increment = abs(0.9/(this.jumpHeight*1.32)/this.whichWay);
			this.counter = 0;
			this.y = this.floor - sin(this.counter += this.increment);		
	}
}

